,"legacy_npc_id":"HG_TVT_02","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_HSM_02_D01","npc_id":"NPC-03","npc_name":"Diệp Hồng Y","faction":"Huyết Sát Môn","kind":"daily","title":"Vạt áo trước gió","npc_text":"Màu áo này dễ khiến người ta nhận ra ta từ xa. Ngươi thấy bất lợi chứ?","min_affection":-100,"pool_index":1,"choices":[{"choice_id":"HG_HSM_02_D01_A","label":"A","player_text":"Nếu nàng muốn, ta sẽ giúp chuẩn bị áo choàng khi cần ẩn hành.","npc_reply":"Ngươi hỏi ta muốn gì trước. Tốt.","affection_delta":5,"trust_delta":1,"scene_id":"HG_HSM_02_D01"},{"choice_id":"HG_HSM_02_D01_B","label":"B","player_text":"Áo của nàng, nàng quyết định.","npc_reply":"Một câu nói ngắn mà dễ nghe.","affection_delta":3,"trust_delta":2,"scene_id":"HG_HSM_02_D01"},{"choice_id":"HG_HSM_02_D01_C","label":"C","player_text":"Đổi hết sang đen cho giống sát thủ đi.","npc_reply":"Ta không mặc áo để giống lời đồn của người khác.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_HSM_02_D01"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_HSM_02","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_HSM_02_D02","npc_id":"NPC-03","npc_name":"Diệp Hồng Y","faction":"Huyết Sát Môn","kind":"daily","title":"Trạm cứu thương nhỏ","npc_text":"Đứa bé mới đến sợ mỗi khi thấy kiếm. Có cách nào khiến nó yên tâm?","min_affection":-100,"pool_index":2,"choices":[{"choice_id":"HG_HSM_02_D02_A","label":"A","player_text":"Cất vũ khí, hạ giọng và để đứa trẻ tự chọn khoảng cách.","npc_reply":"Tốt. Không ép nó phải biết ơn ngay.","affection_delta":5,"trust_delta":1,"scene_id":"HG_HSM_02_D02"},{"choice_id":"HG_HSM_02_D02_B","label":"B","player_text":"Ta đưa đồ chơi và đứng xa để nó quen dần.","npc_reply":"Được. Đừng chạm vào khi nó chưa sẵn lòng.","affection_delta":3,"trust_delta":2,"scene_id":"HG_HSM_02_D02"},{"choice_id":"HG_HSM_02_D02_C","label":"C","player_text":"Bảo nó phải quen máu, ở đây là Huyết Sát.","npc_reply":"Trẻ con không sinh ra để luyện gan cho ngươi.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_HSM_02_D02"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_HSM_02","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_HSM_02_D03","npc_id":"NPC-03","npc_name":"Diệp Hồng Y","faction":"Huyết Sát Môn","kind":"daily","title":"Tin đồn trong quán","npc_text":"Người ở chợ lại kể ta giết cả một làng. Ngươi nghe thì làm gì?","min_affection":-100,"pool_index":3,"choices":[{"choice_id":"HG_HSM_02_D03_A","label":"A","player_text":"Hỏi chứng cứ và không kể lại lời đồn như sự thật.","npc_reply":"Lâu lắm rồi mới có người không vội kết án ta.","affection_delta":5,"trust_delta":1,"scene_id":"HG_HSM_02_D03"},{"choice_id":"HG_HSM_02_D03_B","label":"B","player_text":"Nếu nàng muốn, ta giúp tìm nơi tin ấy bắt đầu.","npc_reply":"Không cần biến mọi lời đồn thành cuộc săn.","affection_delta":3,"trust_delta":2,"scene_id":"HG_HSM_02_D03"},{"choice_id":"HG_HSM_02_D03_C","label":"C","player_text":"Tin có lửa mới có khói, chắc nàng đã làm.","npc_reply":"Ngươi chỉ thích một câu chuyện khiến mình sợ.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_HSM_02_D03"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_HSM_02","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_HSM_02_D04","npc_id":"NPC-03","npc_name":"Diệp Hồng Y","faction":"Huyết Sát Môn","kind":"daily","title":"Buổi đêm không ngủ","npc_text":"Có đêm ta nghe lại tiếng cháy nhà cũ. Ngươi sẽ khuyên thế nào?","min_affection":-100,"pool_index":4,"choices":[{"choice_id":"HG_HSM_02_D04_A","label":"A","player_text":"Nếu muốn, ta ngồi cạnh một lúc, không bắt nàng kể.","npc_reply":"Sự im lặng của ngươi không làm ta khó chịu.","affection_delta":5,"trust_delta":1,"scene_id":"HG_HSM_02_D04"},{"choice_id":"HG_HSM_02_D04_B","label":"B","player_text":"Ta chuẩn bị trà an thần và để nàng tự quyết có dùng không.","npc_reply":"Được. Ta sẽ xem trước thành phần.","affection_delta":3,"trust_delta":2,"scene_id":"HG_HSM_02_D04"},{"choice_id":"HG_HSM_02_D04_C","label":"C","player_text":"Tập giết nhiều hơn thì sẽ hết mơ.","npc_reply":"Vết thương không cần thêm máu để lành.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_HSM_02_D04"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_HSM_02","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_VDC_03_D01","npc_id":"NPC-05","npc_name":"Tạ Thiên Cơ","faction":"Vạn Dược Cốc","kind":"daily","title":"Một nét lệch trên giấy","npc_text":"Nét cuối trận văn này lệch một li. Ngươi thấy là lỗi hay dụng ý?","min_affection":-100,"pool_index":1,"choices":[{"choice_id":"HG_VDC_03_D01_A","label":"A","player_text":"So với các bản cũ, không kích hoạt chỉ vì tò mò.","npc_reply":"Có thể còn sống đủ lâu để tìm ra câu trả lời đấy.","affection_delta":5,"trust_delta":1,"scene_id":"HG_VDC_03_D01"},{"choice_id":"HG_VDC_03_D01_B","label":"B","player_text":"Ta vẽ hai mô hình trên giấy để so.","npc_reply":"Tốt. Giấy chịu sai giỏi hơn người.","affection_delta":3,"trust_delta":2,"scene_id":"HG_VDC_03_D01"},{"choice_id":"HG_VDC_03_D01_C","label":"C","player_text":"Bơm linh lực vào là biết ngay.","npc_reply":"Đó là cách ta mất cả bữa tối, đừng làm.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_VDC_03_D01"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_VDC_03","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_VDC_03_D02","npc_id":"NPC-05","npc_name":"Tạ Thiên Cơ","faction":"Vạn Dược Cốc","kind":"daily","title":"Tính nhầm vì đói","npc_text":"Ta quên ăn rồi hay chưa? Trận bàn vẫn còn ba vòng chưa xong.","min_affection":-100,"pool_index":2,"choices":[{"choice_id":"HG_VDC_03_D02_A","label":"A","player_text":"Ông ăn trước, ta đánh dấu trạng thái để lát tiếp tục.","npc_reply":"À... Đúng là bàn tính không cần cơm, còn ta thì cần.","affection_delta":5,"trust_delta":1,"scene_id":"HG_VDC_03_D02"},{"choice_id":"HG_VDC_03_D02_B","label":"B","player_text":"Ta để phần ăn bên cạnh, nhắc ông nghỉ giữa hai vòng.","npc_reply":"Được, đừng đặt lên nét trận thứ bảy.","affection_delta":3,"trust_delta":2,"scene_id":"HG_VDC_03_D02"},{"choice_id":"HG_VDC_03_D02_C","label":"C","player_text":"Cứ nhịn đi, nghiên cứu quan trọng hơn mạng.","npc_reply":"Ta cần sống để kiểm chứng kết quả.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_VDC_03_D02"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_VDC_03","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_VDC_03_D03","npc_id":"NPC-05","npc_name":"Tạ Thiên Cơ","faction":"Vạn Dược Cốc","kind":"daily","title":"Sáu điểm trên vòng","npc_text":"Sáu điểm đặt quanh vòng không đều. Ngươi ưu tiên kiểm điều gì?","min_affection":-100,"pool_index":3,"choices":[{"choice_id":"HG_VDC_03_D03_A","label":"A","player_text":"Kiểm tâm, bán kính và hệ quy chiếu trước khi sửa điểm.","npc_reply":"Đúng! Không biết lấy gốc nào thì mọi điểm đều sai.","affection_delta":5,"trust_delta":1,"scene_id":"HG_VDC_03_D03"},{"choice_id":"HG_VDC_03_D03_B","label":"B","player_text":"Ta đối chiếu bản vẽ thời trước với bản mới.","npc_reply":"Tìm dữ liệu gốc luôn hữu ích.","affection_delta":3,"trust_delta":2,"scene_id":"HG_VDC_03_D03"},{"choice_id":"HG_VDC_03_D03_C","label":"C","player_text":"Nối đại các điểm thành hình đẹp hơn.","npc_reply":"Đẹp không phải đồng nghĩa hoạt động.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_VDC_03_D03"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_VDC_03","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_VDC_03_D04","npc_id":"NPC-05","npc_name":"Tạ Thiên Cơ","faction":"Vạn Dược Cốc","kind":"daily","title":"Bài giảng hụt người nghe","npc_text":"Ta vừa nói suốt một canh giờ. Ngươi hiểu được bao nhiêu?","min_affection":-100,"pool_index":4,"choices":[{"choice_id":"HG_VDC_03_D04_A","label":"A","player_text":"Ba nguyên tắc; phần không rõ ta sẽ hỏi lại từng ý.","npc_reply":"Tốt, người không giả hiểu là học trò quý.","affection_delta":5,"trust_delta":1,"scene_id":"HG_VDC_03_D04"},{"choice_id":"HG_VDC_03_D04_B","label":"B","player_text":"Ta xin mượn bản vẽ để học thêm.","npc_reply":"Nhớ không mang vào gần lửa.","affection_delta":3,"trust_delta":2,"scene_id":"HG_VDC_03_D04"},{"choice_id":"HG_VDC_03_D04_C","label":"C","player_text":"Ta hiểu hết, khỏi kiểm tra, dù chưa nghe đầu câu.","npc_reply":"Nói dối trước một trận sư còn nguy hiểm hơn sai phép.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_VDC_03_D04"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_VDC_03","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_VDC_04_D01","npc_id":"NPC-04","npc_name":"Bạch Tử Yên","faction":"Vạn Dược Cốc","kind":"daily","title":"Bàn tay rửa lâu","npc_text":"Ta rửa tay sau mỗi ca. Có người bảo ta quá cẩn trọng. Ngươi nghĩ sao?","min_affection":-100,"pool_index":1,"choices":[{"choice_id":"HG_VDC_04_D01_A","label":"A","player_text":"Kiểm soát vệ sinh và quy trình an toàn đáng duy trì.","npc_reply":"Ít nhất có người hiểu vì sao ta không bớt bước ấy.","affection_delta":5,"trust_delta":1,"scene_id":"HG_VDC_04_D01"},{"choice_id":"HG_VDC_04_D01_B","label":"B","player_text":"Ta muốn học quy trình vào phòng thuốc.","npc_reply":"Đến đúng giờ, ta sẽ hướng dẫn.","affection_delta":3,"trust_delta":2,"scene_id":"HG_VDC_04_D01"},{"choice_id":"HG_VDC_04_D01_C","label":"C","player_text":"Rửa cho có lệ, tu sĩ có linh khí rồi.","npc_reply":"Linh khí không thay mọi biện pháp kiểm soát nhiễm bẩn.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_VDC_04_D01"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_VDC_04","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_VDC_04_D02","npc_id":"NPC-04","npc_name":"Bạch Tử Yên","faction":"Vạn Dược Cốc","kind":"daily","title":"Biên bản thiếu chữ ký","npc_text":"Một bản thử đan thiếu người phê duyệt nhưng kết quả tốt. Xếp nó ở đâu?","min_affection":-100,"pool_index":2,"choices":[{"choice_id":"HG_VDC_04_D02_A","label":"A","player_text":"Giữ làm dữ liệu, đánh dấu chưa hợp lệ và không cấp dùng.","npc_reply":"Không xóa kết quả, không giả quy trình. Đúng.","affection_delta":5,"trust_delta":1,"scene_id":"HG_VDC_04_D02"},{"choice_id":"HG_VDC_04_D02_B","label":"B","player_text":"Ta xin người phụ trách làm rõ tại sao thiếu.","npc_reply":"Cần tìm lý do, không chỉ đi xin một chữ ký.","affection_delta":3,"trust_delta":2,"scene_id":"HG_VDC_04_D02"},{"choice_id":"HG_VDC_04_D02_C","label":"C","player_text":"Tự ký hộ, chẳng ai kiểm tra đâu.","npc_reply":"Ngươi không được chạm vào hồ sơ của ta nữa.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_VDC_04_D02"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_VDC_04","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_VDC_04_D03","npc_id":"NPC-04","npc_name":"Bạch Tử Yên","faction":"Vạn Dược Cốc","kind":"daily","title":"Một lời xin lỗi quá muộn","npc_text":"Thầy thuốc phạm sai lầm rồi xin lỗi. Điều gì khiến lời xin lỗi có ý nghĩa?","min_affection":-100,"pool_index":3,"choices":[{"choice_id":"HG_VDC_04_D03_A","label":"A","player_text":"Nhận trách nhiệm, hỗ trợ người bị hại và sửa quy trình.","npc_reply":"Xin lỗi không hoàn lại mạng người, nhưng trách nhiệm không thể bỏ.","affection_delta":5,"trust_delta":1,"scene_id":"HG_VDC_04_D03"},{"choice_id":"HG_VDC_04_D03_B","label":"B","player_text":"Ghi sự cố đầy đủ để người sau tránh lặp lại.","npc_reply":"Đó là một phần cần có.","affection_delta":3,"trust_delta":2,"scene_id":"HG_VDC_04_D03"},{"choice_id":"HG_VDC_04_D03_C","label":"C","player_text":"Xin lỗi xong thì xóa hồ sơ.","npc_reply":"Đó là che giấu, không phải sửa sai.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_VDC_04_D03"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_VDC_04","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_VDC_04_D04","npc_id":"NPC-04","npc_name":"Bạch Tử Yên","faction":"Vạn Dược Cốc","kind":"daily","title":"Y quy giữa đêm","npc_text":"Đệ tử trẻ than quy tắc nhiều làm chậm luyện đan. Ngươi nói sao?","min_affection":-100,"pool_index":4,"choices":[{"choice_id":"HG_VDC_04_D04_A","label":"A","player_text":"Phân biệt bước bảo vệ bệnh nhân và thủ tục thừa, sửa bằng chứng cứ.","npc_reply":"Ta không phản đối cải tiến, chỉ phản đối coi sinh mạng là vật cản.","affection_delta":5,"trust_delta":1,"scene_id":"HG_VDC_04_D04"},{"choice_id":"HG_VDC_04_D04_B","label":"B","player_text":"Ta giúp họ học quy trình cho quen.","npc_reply":"Tốt. Hiểu luật rồi hãy đề nghị sửa.","affection_delta":3,"trust_delta":2,"scene_id":"HG_VDC_04_D04"},{"choice_id":"HG_VDC_04_D04_C","label":"C","player_text":"Cứ bỏ hết, tiến cảnh quan trọng hơn.","npc_reply":"Ta đã thấy điều ấy dẫn đến đâu.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_VDC_04_D04"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_VDC_04","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_TL_01_D01","npc_id":"NPC-01","npc_name":"Trần Minh","faction":"Trung lập","kind":"daily","title":"Một bảng biểu kín ô","npc_text":"Ta từng tưởng Excel là thứ đáng sợ nhất đời. Giờ ngươi nhìn danh sách này xem.","min_affection":-100,"pool_index":1,"choices":[{"choice_id":"HG_TL_01_D01_A","label":"A","player_text":"Ta giúp anh chia thành mục đã xác minh và mục còn chờ.","npc_reply":"May quá. Mình cần hệ thống, không cần thêm một đống giấy.","affection_delta":5,"trust_delta":1,"scene_id":"HG_TL_01_D01"},{"choice_id":"HG_TL_01_D01_B","label":"B","player_text":"Ta sẽ đánh số và làm bản sao.","npc_reply":"Có người phụ là nhẹ cả người.","affection_delta":3,"trust_delta":2,"scene_id":"HG_TL_01_D01"},{"choice_id":"HG_TL_01_D01_C","label":"C","player_text":"Đốt đi cho đỡ việc, tìm ai gặp thì gặp.","npc_reply":"Những cái tên đó không phải việc thừa.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_TL_01_D01"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_TL_01","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisite":"npc_met"},{"scene_id":"HG_TL_01_D02","npc_id":"NPC-01","npc_name":"Trần Minh","faction":"Trung lập","kind":"daily","title":"Người mới tới hội","npc_text":"Một bác lớn tuổi xin tham gia tìm thân, nhưng không biết chữ nơi này. Làm sao giúp?","min_affection":-100,"pool_index":2,"choices":[{"choice_id":"HG_TL_01_D02_A","label":"A","player_text":"Có người đọc/ghi giúp, xác nhận lại bằng tiếng bác hiểu.","npc_reply":"Ta cần một mẫu đăng ký không bỏ người ít học.","affection_delta":5,"trust_delta":1,"scene_id":"HG_TL_01_D02"},{"choice_id":"HG_TL_01_D02_B","label":"B","player_text":"Ta hướng dẫn bác nhận dấu hiệu hội và người phụ trách.","npc_reply":"Hay, đỡ để bác lạc giữa đám đông.","affection_delta":3,"trust_delta":2,"scene_id":"HG_TL_01_D02"},{"choice_id":"HG_TL_01_D02_C","label":"C","player_text":"Không đọc được thì không cho đăng ký.","npc_reply":"Hội này mở vì người lạc đường, không phải vì người biết chữ.","affection_delta":-4,"trust_delta":-2,"scene_id":"HG_TL_01_D02"}],"repeatable":true,"one_time_per_life":false,"story_reward":false,"legacy_npc_id":"HG_TL_01","world":"Hạ Giới","requires_npc_available":true,"main_quest_gate":false,"prerequisit